APP_REDESIGN_CSS = "/* SunPark UI refresh. Loaded only by the opt-in Claude test route. */\n@font-face {\n  font-family: 'Golos Text'; font-style: normal; font-weight: 400 900;\n  font-display: swap; src: url('data:font/woff2;base64,') format('woff2');\n}\n:root {\n  --font-ui: 'Golos Text', -apple-system, BlinkMacSystemFont, Arial, sans-serif;\n  --paper: #f5f7f0; --ink: #183329; --body-ink: #20382c; --muted: #596d60;\n  --green: #335d43; --button-ink: #f7faed; --line: #d0dacc; --soft: #e8efe2;\n  --accent: #46704e; --surface: #ffffff; --surface-alt: #edf3e7; --field-line: #7d927e;\n  --danger: #b23b2b; --warning: #80530e; --warning-bg: #fff0cf;\n  --nav-height: 72px; --nav-clearance: var(--nav-outer-height, calc(var(--nav-height) + var(--safe-bottom)));\n  background: var(--paper); color: var(--body-ink); font-family: var(--font-ui);\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]) {\n    --paper: #102119; --ink: #f2f5e9; --body-ink: #e6eddf; --muted: #b6c4b7;\n    --green: #b9d99a; --button-ink: #12271a; --line: #385441; --soft: #203c2c;\n    --accent: #b9d99a; --surface: #172e22; --surface-alt: #1e3b2b; --field-line: #75917d;\n    --danger: #ffb29e; --warning: #f2ce82; --warning-bg: #4a391e;\n  }\n}\n:root[data-theme=dark] {\n  --paper: #102119; --ink: #f2f5e9; --body-ink: #e6eddf; --muted: #b6c4b7;\n  --green: #b9d99a; --button-ink: #12271a; --line: #385441; --soft: #203c2c;\n  --accent: #b9d99a; --surface: #172e22; --surface-alt: #1e3b2b; --field-line: #75917d;\n  --danger: #ffb29e; --warning: #f2ce82; --warning-bg: #4a391e;\n}\nbody { font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }\nbody, button, input, textarea, select, h1, h2, h3, h4, .page-title, .ruled-title,\n.native-title, .calendar-month, .concept-title, .loading-brand, .complex-intro h1 {\n  font-family: var(--font-ui) !important;\n}\nbutton, input, textarea, select { letter-spacing: 0; }\nh1, h2, h3, .page-title, .native-title, .concept-title { color: var(--ink); letter-spacing: -.035em; }\n.page-title, .service-view > .page-title, #menu-hub > .page-title, .concept-title, .native-title {\n  font-size: clamp(25px, 7.2vw, 30px); line-height: 1.15; font-weight: 650; margin: 12px 0 20px;\n}\n.ruled-title { font-size: 28px; line-height: 1.2; font-weight: 650; letter-spacing: -.035em; }\n.concept-subtitle, .native-subtitle, .service-subtitle { font-size: 15px; line-height: 1.6; color: var(--muted); margin: -8px 0 20px; }\n.concept-hint, .native-hint, .catalog-hint, .cart-order-note { color: var(--muted); font-size: 14px; line-height: 1.6; }\n.back-link, .view-back .back-link { min-height: 44px; font-size: 14px; font-weight: 500; color: var(--muted); }\n.view-back { padding-bottom: 2px; }\nbutton:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {\n  outline: 3px solid var(--green); outline-offset: 3px;\n}\n.primary-button, .secondary-button {\n  min-height: 52px; border-radius: 14px; padding: 14px 16px; font-size: 16px; line-height: 1.4; font-weight: 650;\n  box-shadow: none; transition: opacity .15s ease, transform .12s ease;\n}\n.primary-button { background: var(--green); color: var(--button-ink); border: 1px solid transparent; }\n.secondary-button { background: var(--surface); border: 1px solid var(--line); color: var(--ink); }\n.primary-button:active, .secondary-button:active { transform: scale(.985); }\n.primary-button:disabled, .secondary-button:disabled { opacity: .45; }\n.text-button { min-height: 44px; color: var(--green); font-size: 14px; }\n\n/* Discovery: generous photographs, clear labels, one compact location block. */\n.home-services h2, #home-services-title { font-size: clamp(23px, 6.4vw, 27px); line-height: 1.25; font-weight: 650; margin: 0 0 16px; }\n.complex-intro p { color: var(--muted); font-size: 14px; line-height: 1.5; }\n.direction-grid { gap: 12px; }\n.direction-grid .service-card { border: 1px solid var(--line); border-radius: 20px; background: var(--surface); box-shadow: none; }\n.direction-grid .service-thumbnail { height: clamp(96px, calc((var(--viewport-height) - var(--safe-top) - var(--nav-clearance) - 380px) / 2), 146px); }\n.direction-grid .service-card-copy { padding: 13px 12px 15px; gap: 5px; }\n.direction-grid .service-card-copy strong { font-size: 21px; line-height: 1.15; font-weight: 650; color: var(--ink); letter-spacing: -.025em; }\n.direction-grid .service-card-copy > span { font-size: 13px; line-height: 1.45; color: var(--muted); }\n.home-location { margin-top: 24px; padding-top: 18px; border-top: 1px solid var(--line); }\n.home-location p { font-size: 14px; line-height: 1.6; margin-bottom: 8px; }\n.home-location a { display: inline-flex; align-items: center; min-height: 44px; font-size: 14px; font-weight: 600; margin-right: 20px; }\n.concept-photo, .service-photos { border-radius: 20px; }\n.concept-photo { margin: 20px 0; aspect-ratio: 16 / 9; }\n.concept-photo > button, .gallery-controls .icon-button { width: 44px; height: 44px; border-radius: 50%; }\n.photo-fallback { color: var(--muted); background: var(--surface-alt); text-decoration: none !important; font-size: 14px; line-height: 1.5; }\n.concept-section-title { font-size: 21px; font-weight: 650; line-height: 1.3; margin: 28px 0 14px; }\n.restaurant-menu-link { min-height: 82px; margin: 20px 0 12px; padding: 18px; border: 0; border-radius: 18px; background: var(--green); color: var(--button-ink); }\n.restaurant-menu-link .restaurant-menu-copy strong { font-size: 18px; font-weight: 650; color: inherit; }\n.restaurant-menu-link .restaurant-menu-copy > span { font-size: 13px; color: inherit; opacity: .85; }\n.restaurant-menu-link > .icon { color: inherit; }\n.concept-choice { display: grid; grid-template-columns: 22px minmax(0,1fr); gap: 10px 12px; width: 100%; padding: 15px; margin: 10px 0; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); }\n.concept-choice > .icon { width: 22px; height: 22px; grid-row: 1 / 3; align-self: start; margin-top: 2px; color: var(--muted); }\n.concept-choice strong { font-size: 16px; line-height: 1.4; font-weight: 600; }\n.concept-choice small { font-size: 13px; line-height: 1.5; color: var(--muted); margin-top: 5px; }\n.concept-choice > b { grid-column: 2; color: var(--ink); max-width: none; font-size: 16px; font-weight: 650; white-space: normal; }\n.concept-choice.selected { background: var(--surface-alt); border-color: var(--green); }\n.concept-choice.selected > .icon { color: var(--green); }\n\n/* A visible, consistently placed next action for long booking screens. */\n.journey-progress { margin: 8px 0 22px; }\n.journey-progress-label { display: flex; justify-content: space-between; gap: 12px; font-size: 12px; font-weight: 600; color: var(--muted); margin-bottom: 9px; }\n.journey-progress-track { display: flex; gap: 5px; }\n.journey-progress-track > span { flex: 1; height: 3px; background: var(--line); border-radius: 3px; }\n.journey-progress-track > .complete { background: var(--green); }\n#concept-content.has-refined-dock { padding-bottom: calc(var(--dock-height, 112px) + 20px); }\n.concept-footer.refined-dock, .cart-actions {\n  position: fixed; z-index: 8; bottom: var(--nav-clearance); margin: 0; padding: 12px 0;\n  left: max(calc(var(--page-gutter, 16px) + var(--safe-left)), calc((100% - var(--content-width, 960px)) / 2 + var(--page-gutter, 16px)));\n  right: max(calc(var(--page-gutter, 16px) + var(--safe-right)), calc((100% - var(--content-width, 960px)) / 2 + var(--page-gutter, 16px)));\n  background: var(--paper); border-top: 1px solid var(--line); display: grid; gap: 6px;\n}\n.concept-footer.refined-dock .primary-button { margin: 0; }\n.refined-dock-total { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding: 1px 0 5px; }\n.refined-dock-total > span { font-size: 12px; color: var(--muted); }\n.refined-dock-total > strong { font-size: 19px; font-weight: 650; color: var(--ink); white-space: nowrap; }\n.cart-actions > .primary-button, .cart-actions > .secondary-button { margin: 0; }\n.cart-actions > .secondary-button { min-height: 44px; padding: 8px; border-color: transparent; background: transparent; color: var(--muted); font-size: 14px; }\n#cart-view:has(.cart-actions:not([hidden])) { padding-bottom: calc(var(--dock-height, 112px) + 20px); }\n.concept-footer.refined-dock .text-button { margin: 0; padding: 8px; }\nhtml { scroll-padding-top: calc(var(--safe-top) + 12px); scroll-padding-bottom: calc(var(--nav-clearance) + 16px); }\nhtml:has(#concept-view:not([hidden]) .refined-dock), html:has(#cart-view:not([hidden]) .cart-actions:not([hidden])) { scroll-padding-bottom: calc(var(--nav-clearance) + 144px); }\nhtml:has(body.is-keyboard-open) { scroll-padding-bottom: 16px; }\nbody.is-keyboard-open .concept-footer.refined-dock { position: static; margin-top: 20px; }\nbody.is-keyboard-open #concept-content.has-refined-dock { padding-bottom: 0; }\n.concept-month-controls { margin: 20px 0 14px; gap: 10px; }\n.concept-month-controls > span { font-size: 14px; font-weight: 600; }\n.concept-month-controls > button { min-width: 44px; min-height: 44px; font-size: 12px; line-height: 1.4; }\n.date-control { min-height: 52px; border-radius: 14px; border: 1px solid var(--field-line); background: var(--surface); color: var(--ink); font-size: 15px; padding: 12px 14px; margin-right: 8px; }\n.hotel-date-range { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; margin: 22px 0; }\n.hotel-date-range .date-control { display: grid; gap: 6px; text-align: left; margin: 0; min-height: 80px; }\n.date-caption { font-size: 12px; font-weight: 400; color: var(--muted); }\n.hotel-date-range .date-control > strong { font-size: 15px; font-weight: 600; }\n.concept-counter { min-height: 68px; padding: 14px 0; }\n.concept-counter > span, .counter-row > .field-label { font-size: 15px; font-weight: 500; }\n.counter-label { display: grid; gap: 4px; font-size: 15px; font-weight: 500; }\n.session-availability { font-size: 12px; color: var(--muted); font-weight: 400; }\n.number-stepper, .quantity-controls, .cart-stepper { border: 1px solid var(--line); border-radius: 14px; background: var(--surface); }\n.number-stepper button, .quantity-controls button, .cart-stepper .icon-button { width: 44px; min-height: 44px; height: 44px; background: transparent; color: var(--green); }\n.concept-counter .number-stepper .icon-button { width: 44px; min-width: 44px; min-height: 44px; height: 44px; }\n.number-stepper output, .quantity-controls output, .cart-stepper output { min-width: 36px; font-size: 16px; font-weight: 600; font-variant-numeric: tabular-nums; }\n.concept-drums { margin: 16px 0 20px; }\n.concept-wheel { height: 208px; padding-top: 78px; padding-bottom: 78px; }\n.concept-wheel .selected { font-size: 40px; font-weight: 600; transform: none; font-stretch: normal; }\n.concept-drum-group > span { font-size: 13px; color: var(--muted); }\n#concept-content[data-screen=time] .journey-progress { margin-bottom: 14px; }\n#concept-content[data-screen=time] .concept-title { margin: 8px 0 14px; }\n#concept-content[data-screen=time] > .concept-tag { margin: 0 0 6px; }\n#concept-content[data-screen=time] .concept-counter { margin: 6px 0; min-height: 60px; padding: 8px 0; }\n#concept-content[data-screen=time] .concept-month-controls { margin: 10px 0; }\n#concept-content[data-screen=time] .concept-month-controls > button { padding: 10px; }\n#concept-content[data-screen=time] > .date-control { display: block; width: 100%; margin-right: 0; }\n#concept-content[data-screen=time] .concept-drums { margin: 10px 0 8px; }\n#concept-content[data-screen=time] .concept-total { display: none; }\n#concept-content[data-screen=time] .concept-summary > div { display: flex; justify-content: space-between; padding: 8px 0; border: 0; }\n.concept-summary { margin: 0; padding: 0; }\n.concept-summary > div { grid-template-columns: minmax(0, .9fr) minmax(0, 1.5fr); gap: 12px; padding: 15px 0; border-color: var(--line); }\n.concept-summary dt { font-size: 13px; line-height: 1.5; color: var(--muted); }\n.concept-summary dd { font-size: 15px; line-height: 1.5; font-weight: 500; color: var(--ink); }\n.concept-total { margin: 22px 0; gap: 12px; }\n.concept-total > span { font-size: 14px; color: var(--muted); }\n.concept-total strong { font-size: 28px; line-height: 1.2; font-weight: 650; letter-spacing: -.03em; }\n.form-field { margin: 20px 0; }\n.field-label { display: block; font-size: 14px; line-height: 1.5; font-weight: 600; margin-bottom: 8px; color: var(--ink); }\ninput, textarea, select, .field-input, #concept-content .field-input, #concept-content select {\n  font-size: 16px; min-height: 54px; line-height: 1.4; padding: 14px; border: 1px solid var(--field-line); border-radius: 14px; background: var(--surface); color: var(--ink);\n}\ninput:focus, textarea:focus, select:focus { border-color: var(--green); box-shadow: 0 0 0 2px var(--soft); }\ninput[aria-invalid=true] { border-color: var(--danger); }\n.field-error, .native-error { color: var(--danger); font-size: 13px; line-height: 1.5; }\n.concept-notice { padding: 16px; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); gap: 12px; }\n.concept-notice strong { font-size: 14px; font-weight: 600; }\n.concept-notice p { font-size: 13px; line-height: 1.55; color: var(--muted); }\n.concept-room { padding: 20px; border: 1px solid var(--line); border-radius: 20px; background: var(--surface); margin: 18px 0; }\n.concept-room h2 { font-size: 22px; margin: 0 0 12px; }\n.concept-room .primary-button { font-size: 16px; }\n.concept-room .concept-total { margin: 20px 0; }\n\n/* Menu: stable rows, readable descriptions and a persistent quantity footer. */\n#menu-hub > .page-title { margin: 8px 0 16px; }\n.search { min-height: 50px; border-radius: 14px; margin: 12px 0; padding: 0 14px; background: var(--surface); border: 1px solid var(--line); }\n.search input { min-height: 48px; padding: 10px 0; background: transparent; border: 0; box-shadow: none; }\n.search .icon { width: 21px; height: 21px; }\n#groups.group-tabs, #concept-content .group-tabs, .group-tabs {\n  display: flex; gap: 4px; padding: 4px; margin: 12px 0; border: 1px solid var(--line); border-radius: 15px; background: var(--surface); overflow-x: auto;\n}\n#groups.group-tabs button, #concept-content .group-tabs button, .group-tabs button {\n  flex: 1 0 auto; min-height: 44px; padding: 9px 12px; border: 0; border-radius: 11px; font-size: 14px; line-height: 1.4; font-weight: 600; background: transparent; color: var(--muted); white-space: nowrap;\n}\n#groups.group-tabs button[aria-pressed=true], #concept-content .group-tabs button[aria-pressed=true], .group-tabs button[aria-pressed=true] {\n  border: 0; background: var(--soft); color: var(--ink);\n}\n#categories.category-rail { padding-top: 8px; padding-bottom: 12px; margin-bottom: 8px; border: 0; }\n.category-chip { min-height: 44px; padding: 10px 15px; border-radius: 999px; font-size: 14px; font-weight: 500; background: var(--surface); border: 1px solid var(--line); color: var(--ink); }\n.category-chip[aria-pressed=true] { background: var(--green); border-color: var(--green); color: var(--button-ink); }\n#catalog-view:not(.is-searching) > #section-title { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }\n#catalog-view.is-searching > #section-title { font-size: 21px; margin: 20px 0 12px; }\n.items { display: grid; gap: 12px; padding-top: 4px; }\n.items .subsection { font-size: 18px; font-weight: 600; margin: 12px 0 0; }\n.items .item-row {\n  display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 12px; align-items: center; padding: 16px;\n  border: 1px solid var(--line); border-radius: 18px; background: var(--surface); box-shadow: none;\n}\n.items .item-open, .items .item-row.has-quantity .item-open { grid-column: 1 / -1; display: block; min-height: 44px; padding: 0; }\n.items .item-row .name { font-size: 17px; line-height: 1.35; font-weight: 600; color: var(--ink); }\n.items .item-description { font-size: 14px; line-height: 1.55; font-weight: 400; color: var(--muted); }\n.items .item-row > .price, .items .item-row.has-quantity > .price { grid-column: 1; grid-row: 2; justify-self: start; text-align: left; max-width: none; font-size: 16px; font-weight: 650; color: var(--ink); }\n.items .item-actions { grid-column: 2; grid-row: 2; }\n.items .item-actions .icon-button { min-height: 44px; height: 44px; width: 44px; }\n.cart-launcher { min-height: 58px; border: 0; border-radius: 17px; padding: 14px 16px; font-size: 16px; box-shadow: 0 6px 18px #00000018; }\n.cart-badge { min-width: 24px; font-size: 13px; font-weight: 650; }\n.cart-summary { display: flex; justify-content: space-between; gap: 16px; padding: 18px; margin: 20px 0; border: 1px solid var(--line); border-radius: 18px; background: var(--surface); box-shadow: none; }\n.cart-summary > span { font-size: 14px; color: var(--muted); }\n.cart-summary strong { font-size: 24px; line-height: 1.3; color: var(--ink); }\n.cart-row { padding: 20px 0; border-bottom: 1px solid var(--line); }\n.cart-row-name { font-size: 17px; line-height: 1.4; font-weight: 600; }\n.cart-row-price { font-size: 17px; line-height: 1.4; font-weight: 600; }\n.cart-line-remove { color: var(--muted); min-width: 44px; min-height: 44px; }\n.cart-order-note, #cart-hint { font-size: 14px; line-height: 1.65; color: var(--muted); }\n\n/* Bottom sheets share the same fields, stepper and action hierarchy. */\ndialog { border: 1px solid var(--line); border-bottom: 0; border-radius: 24px 24px 0 0; background: var(--paper); color: var(--ink); padding: 26px 18px max(20px, var(--safe-bottom)); }\ndialog::backdrop { background: #04120b99; backdrop-filter: blur(3px); }\ndialog::before { content: ''; display: block; width: 36px; height: 4px; background: var(--line); border-radius: 4px; margin: -12px auto 20px; }\ndialog h2 { font-size: 26px; line-height: 1.2; font-weight: 650; padding-right: 30px; }\ndialog h3 { font-size: 16px; font-weight: 600; }\n.close-dialog { width: 44px; height: 44px; border-radius: 50%; color: var(--muted); }\n.dish-section { font-size: 13px; margin: 0 0 12px; }\n.dish-price { font-size: 18px; line-height: 1.5; font-weight: 600; margin: 18px 0; }\n.dish-description { font-size: 15px; line-height: 1.65; }\n.detail-rule { margin: 20px 0; }\n.option-choice { min-height: 64px; padding: 13px; border-radius: 14px; background: var(--surface); border-color: var(--line); }\n.option-choice:has(input:checked) { border-color: var(--green); background: var(--surface-alt); }\n.option-choice input { width: 20px; min-height: 20px; height: 20px; padding: 0; }\n.option-cart-count { font-size: 12px; line-height: 1.5; }\n.dish-actions { position: sticky; bottom: calc(-1 * max(20px, var(--safe-bottom))); margin: 20px -18px calc(-1 * max(20px, var(--safe-bottom))); padding: 14px 18px max(20px, var(--safe-bottom)); background: var(--paper); border-top: 1px solid var(--line); }\n.dish-quantity { margin: 0 0 14px; font-size: 15px; }\n.dish-actions .primary-button { margin-top: 0; }\n.dish-actions .secondary-button { margin-top: 8px; min-height: 44px; background: transparent; border-color: transparent; color: var(--muted); }\n.calendar-month { font-size: 24px; font-weight: 600; line-height: 1.3; }\n.calendar-day { min-height: 40px; border-radius: 12px; font-size: 15px; }\n.calendar-weekdays { color: var(--muted); }\n\n/* Plans, receipts, staff tables and messaging use semantic status colours. */\n.concept-order { padding: 18px; margin: 14px 0; border: 1px solid var(--line); border-radius: 18px; background: var(--surface); }\n.concept-order > div { align-items: start; gap: 12px; }\n.concept-order > div > strong { font-size: 21px; font-weight: 650; }\n.concept-order p { font-size: 15px; font-weight: 500; margin: 12px 0 7px; }\n.concept-order small { font-size: 13px; line-height: 1.5; color: var(--muted); }\n.concept-order > b { color: var(--ink); font-size: 18px; font-weight: 650; }\n.concept-tag { font-size: 12px; font-weight: 600; padding: 7px 10px; border-radius: 9px; line-height: 1.35; background: var(--soft); color: var(--muted); }\n.concept-tag[data-status=paid] { background: var(--green); color: var(--button-ink); }\n.concept-tag[data-status=hold], .concept-tag[data-status=checkout], .concept-tag[data-status=payment_review] { background: var(--warning-bg); color: var(--warning); }\n.concept-tag[data-status=expired], .concept-tag[data-status=payment_error] { border: 1px solid var(--line); color: var(--muted); background: transparent; }\n.concept-order .concept-tag { font-size: 11px; max-width: 46%; }\n.concept-empty { margin: 28px 0; padding: 28px 20px; border: 1px solid var(--line); border-radius: 20px; background: var(--surface); }\n.concept-empty h2 { font-size: 22px; line-height: 1.3; font-weight: 600; }\n.concept-empty p { font-size: 14px; line-height: 1.6; color: var(--muted); }\n.concept-qr { width: min(100%, 300px); padding: 20px; border-radius: 20px; margin: 28px auto 20px; }\n.concept-code { font-size: 25px; font-weight: 600; letter-spacing: 2px; }\n.concept-tables { grid-template-columns: repeat(auto-fit, minmax(110px,1fr)); gap: 12px; }\n.concept-table { min-height: 104px; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); }\n.concept-table strong { font-size: 22px; }\n.concept-table small { font-size: 12px; }\n.concept-table.selected { border-color: var(--green); background: var(--green); color: var(--button-ink); }\n.action-row { min-height: 64px; gap: 14px; font-size: 16px; line-height: 1.45; padding: 17px 0; border-color: var(--line); }\n.action-row > .icon:first-child { width: 24px; height: 24px; color: var(--green); }\n.request-row { padding: 18px 0; }\n.request-row strong { font-size: 17px; line-height: 1.4; font-weight: 600; }\n.request-row p { font-size: 14px; line-height: 1.55; color: var(--muted); }\n.chat-heading .page-title { font-size: 21px; line-height: 1.3; margin: 0; }\n.chat-bubble { font-size: 15px; line-height: 1.6; border-radius: 18px 18px 18px 5px; box-shadow: none; padding: 13px 15px; }\n.chat-bubble.mine { border-radius: 18px 18px 5px 18px; background: var(--surface-alt); }\n.chat-bubble time, .chat-date { font-size: 12px; color: var(--muted); }\n.chat-status { font-size: 12px; }\n.chat-form textarea, .chat-compose textarea { min-height: 48px; border-radius: 16px; }\n#chat-send { border-radius: 15px; background: var(--green); color: var(--button-ink); }\n.app-nav { background: var(--paper); border-top: 1px solid var(--line); }\n.app-nav button { min-height: 54px; padding: 7px 4px; border-radius: 14px; color: var(--muted); font-size: 12px; font-weight: 500; line-height: 1.4; }\n.app-nav button[aria-current=page] { background: var(--soft); color: var(--ink); font-weight: 600; }\n.app-nav .icon { width: 24px; height: 24px; }\n.app-nav button[aria-current=page] .icon { color: var(--green); }\n.cart-toast { border-radius: 14px; font-size: 14px; line-height: 1.5; }\n.loading-line { background: var(--soft); border-radius: 12px; }\n\n@media (max-width: 360px) {\n  .direction-grid { gap: 10px; }\n  .direction-grid .service-card-copy { padding: 11px 10px 13px; }\n  .direction-grid .service-card-copy strong { font-size: 19px; }\n  .direction-grid .service-card-copy > span { font-size: 12px; }\n  .concept-choice { padding: 13px; }\n  .concept-choice strong { font-size: 15px; }\n  .items .item-row { padding: 14px; }\n  .items .item-row .name { font-size: 16px; }\n  .app-nav button { font-size: 11px; }\n}\n@media (min-width: 700px) and (max-height: 560px) {\n  .direction-grid .service-thumbnail { height: 80px; }\n  .direction-grid .service-card-copy { padding: 9px 11px 11px; }\n  .direction-grid .service-card-copy strong { font-size: 20px; }\n}\n@media (min-width: 361px) {\n  .concept-choice { grid-template-columns: 22px minmax(0,1fr) auto; align-items: start; }\n  .concept-choice > b { grid-column: 3; grid-row: 1; max-width: 110px; text-align: right; font-size: 15px; }\n}\n@media (max-height: 720px) {\n  .concept-wheel { height: 156px; padding-top: 52px; padding-bottom: 52px; }\n}\n@media (max-height: 560px) {\n  .menu-back, #categories.category-rail { position: static; }\n}\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }\n}\n"
